import{Z as s,e as i,f as a,a0 as t}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Checkboxes","description":"","frontmatter":{},"headers":[],"relativePath":"fields/checkboxes.md","filePath":"fields/checkboxes.md","lastUpdated":1780994610000}'),n={name:"fields/checkboxes.md"};function o(l,e,r,h,p,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="checkboxes" tabindex="-1">Checkboxes <a class="header-anchor" href="#checkboxes" aria-label="Permalink to &quot;Checkboxes&quot;">​</a></h1><p>Use Checkboxes when someone can choose more than one option from a list.</p><p>Use Checkboxes for multiple-choice questions where more than one answer can be true. If only one answer should be selected, use Radio or Dropdown instead.</p><h2 id="allow-several-interests" tabindex="-1">Allow Several Interests <a class="header-anchor" href="#allow-several-interests" aria-label="Permalink to &quot;Allow Several Interests&quot;">​</a></h2><p>Add a Checkboxes field named <strong>Interests</strong> to a signup form and enter the options <strong>Events</strong>, <strong>News</strong> and <strong>Training</strong>. Save the form, select two options and submit. Confirm that both choices are saved. Use Radio or Dropdown when the visitor must choose only one option.</p><h2 id="key-settings" tabindex="-1">Key Settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key Settings&quot;">​</a></h2><ul><li><strong>Options</strong> - Define the available choices. Keep option values stable once submissions, exports or integrations depend on them.</li><li><strong>Layout</strong> - Choose whether options appear vertically or horizontally.</li><li><strong>Toggle checkbox</strong> - Adds a single control for selecting or clearing the full option set.</li><li><strong>Minimum and maximum selections</strong> - Enforce how many options must or can be selected.</li><li><strong>Default value</strong> - Preselect one or more options for new submissions.</li></ul><h2 id="bulk-add-options" tabindex="-1">Bulk Add Options <a class="header-anchor" href="#bulk-add-options" aria-label="Permalink to &quot;Bulk Add Options&quot;">​</a></h2><p>Use Bulk add options when you need to add a long list, such as interests, countries, services or another repeated option set. You can start from Formie’s predefined options, choose which source field should be used for the label and value, then append those options to the field or replace the existing options.</p><p>You can also paste your own options into the bulk editor. Use one option per line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Support|support</span></span>
<span class="line"><span>Billing|billing</span></span>
<span class="line"><span>Sales|sales</span></span></code></pre></div><p>If you only provide one value on a line, Formie uses it for both the label and value.</p><h2 id="option-sources" tabindex="-1">Option Sources <a class="header-anchor" href="#option-sources" aria-label="Permalink to &quot;Option Sources&quot;">​</a></h2><p>For longer or integration-driven lists, set <strong>Options</strong> to <strong>Predefined</strong> or <strong>Integration</strong> instead of maintaining a static options table. See <a href="/fields/option-sources">Option Sources</a>.</p><h2 id="option-availability" tabindex="-1">Option Availability <a class="header-anchor" href="#option-availability" aria-label="Permalink to &quot;Option Availability&quot;">​</a></h2><p>Use the row menu on an option to set its <strong>availability</strong>:</p><ul><li><strong>Visible</strong> — Shown and selectable (default).</li><li><strong>Hidden</strong> — Removed from the front-end form without deleting the option. Existing submissions keep their stored value and label in the control panel, exports and email notifications.</li><li><strong>Disabled</strong> — Shown on the front-end form with HTML <code>disabled</code> so it is visible but cannot be selected.</li></ul><p>Only one state applies at a time. Prefer hiding over deleting an option once submissions may reference its value.</p><h2 id="overriding-options" tabindex="-1">Overriding Options <a class="header-anchor" href="#overriding-options" aria-label="Permalink to &quot;Overriding Options&quot;">​</a></h2><p>If the options need to come from template logic, you can override the field’s <code>options</code> before rendering the form. See <a href="/templates/overriding-settings">Overriding Settings</a>.</p><h2 id="submitted-value" tabindex="-1">Submitted Value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted Value&quot;">​</a></h2><p>Checkboxes store multiple selected option values. In templates, exports and integrations, treat the value as a list of selected options rather than a single string.</p><p>When querying or saving submissions through GraphQL, the field handle is used as the field name. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> if you need to confirm the generated input type for a specific form.</p><h2 id="theme-config" tabindex="-1">Theme Config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme Config&quot;">​</a></h2><p>The Checkboxes field can be targeted with the <code>checkboxes</code> theme config key.</p><p>See <a href="/reference/theme-tag-reference#checkboxes-field">Checkboxes Field theme config</a> for the full list of field-specific theme tags.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        checkboxes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            fieldOptions: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-checkbox-options&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            fieldOptionLabel: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-checkbox-label&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use theme config for class and attribute changes. Use a template override only when you need to change the option markup itself.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="front-end-reference" tabindex="-1">Front-End Reference <a class="header-anchor" href="#front-end-reference" aria-label="Permalink to &quot;Front-End Reference&quot;">​</a></h2><p>The front-end docs live on the separate browser UI reference site and cover rendered markup, data attributes, styling classes and JavaScript behaviour for custom front-end implementations.</p><ul><li><a href="https://docs.verbb.io/formie/browser/ui-reference/fields/checkboxes" target="_blank" rel="noreferrer">Checkboxes</a></li></ul><h2 id="related-fields" tabindex="-1">Related Fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related Fields&quot;">​</a></h2><ul><li>Use <a href="/fields/radio">Radio</a> when exactly one visible option should be selected.</li><li>Use <a href="/fields/dropdown">Dropdown</a> when the option list is long or should take less space.</li></ul>`,34)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
